# Count how many OTHER rects' borders each rect's interior touches
border_touch_count = {}
for n1, (r1, b1, l1, r1b) in rects.items():
    count = 0
    for n2, (r2, b2, l2, r2b) in rects.items():
        if n1 == n2: continue

        i1r_start, i1r_end = r1 + 1, b1 - 1
        i1c_start, i1c_end = l1 + 1, r1b - 1

        touches_border = False
        for r in range(i1r_start, i1r_end + 1):
            for c in range(i1c_start, i1c_end + 1):
                if r == r2 or r == b2 or c == l2 or c == r2b:
                    touches_border = True
                    break
            if touches_border: break

        if touches_border:
            count += 1

    border_touch_count[n1] = count
    print(f"{n1}: interior touches {count} other rect borders")

print(f"\nCounts: {border_touch_count}")

